import IntlMessageFormat from 'intl-messageformat';
import { warn, error } from './util';

const PSEUDO_LANGUAGE_TAG = 'pd-KV';
export interface Medusa {
  [propName: string]: string;
}
export interface StringData {
  [propName: string]: {
    [propName: string]: string;
  };
}
export interface Description {
  id: string;
  defaultMessage?: string;
  defaultString?: string;
}

export interface Variable {
  [propName: string]: any; 
}



export interface FormatOptions {
  name?: string; // instance name, default is 'default',
  component?: object;
  tagName?: string;
  React?: {
    isValidElement: Function;
    createElement: Function;
  }; // React  
}
// 格式支持：en-US ， en_US,  en_us
function formatLocale(locale = ''): string {
  if (typeof locale !== 'string') {
    error('"locale" is not a string, please check your input locale');
    locale = '';
  }
  let result = locale.toLowerCase();
  result = result.replace('-', '_');
  return result;
}

function truncationCompare(locale: string, superior: string): boolean {
  if (locale === superior) {
    return true;
  }
  const localeMatch = locale.match(/(\S*)_/);
  if (localeMatch) {
    const localTruncation = localeMatch[1];
    return truncationCompare(localTruncation, superior);
  }
  return false;
}

function isSuperior(locale: string, superior: string): boolean {
  // en-us , en_us, En-us等为en的上级
  const localeFormat = formatLocale(locale);
  const superiorFormat = formatLocale(superior);
  if (localeFormat === superiorFormat) {
    return true;
  }
  // 对localeFormat进行截断后判断
  return truncationCompare(localeFormat, superiorFormat);
}
export default class StringFormat {
  // dictionary = {
  //   'eee.ddd': {
  //     format: function (): string{}
  //   },
  //   'address.address_book.title': {
  //     format: function (): string{}
  //   }
  // }
  private dictionary: {
    [propName: string]: any; // eslint-disable-line
  };
  
  private strings: StringData;

  private locale: string;

  private medusa?: Medusa; 

  /**
   *  @param locale Languages that need to be localized
   *  @param strings Data dictionary, ICU grammar
   */
  constructor(locale: string, strings: StringData) {
    this.dictionary = {};
    // 格式支持：en-US ， en_US,  en_us
    this.locale = locale || '';
    // strings[locale] = {
    //   'eee.ddd': '我有 ${count}  条文案',
    //   'address.address_book.title': '我的地址是',
    // }
    if (!strings) {
      warn(`param "strings" is undefined, please check your incoming`);
      strings = {};
    }

    if(strings.medusa){
      this.medusa = strings.medusa;
      delete strings.medusa;
    }
    this.strings = strings;

    let localeStrings = strings[locale];
    if (!localeStrings) {
      // 因en_us en-us en-Us等格式不同没找到对应文案的，转换格式后再找
      Object.keys(strings).forEach((language): void => {
        if (formatLocale(language) === formatLocale(locale)) {
          warn(`no string list for locale: ${locale} , will replace it with ${language}`);
          localeStrings = strings[language];
        }
      });
      // 因en_us en-us en-Us可找到en上级
      if (!localeStrings) {
        Object.keys(strings).forEach((language): void=> {
          if (isSuperior(locale, language)) {
            warn(`no value for locale: ${locale} , will replace it with${language}`);
            localeStrings = strings[language];
          }
        });
      }
    }
    if (!localeStrings || (localeStrings && Object.keys(localeStrings).length === 0)) {
      warn(`no value for locale: ${locale}, please check your second param`);
      localeStrings = {};
    }
    Object.keys(localeStrings).forEach((id): void => {
      try{
        const formatter = new IntlMessageFormat(localeStrings[id], locale);
        this.dictionary[id] = formatter;
      }catch(e){
        this.dictionary[id] = {};        
        error(e);
      }
    });
  }

  /**
   * 获取 strings
   */
  getStrings(): StringData{
    return this.strings;
  }

  formatString(formatter: IntlMessageFormat,  variables: Variable, id: string): string{
    const {medusa, locale}= this;
    let formatedString = formatter.format(variables);
    if( medusa && medusa.app_name && locale === PSEUDO_LANGUAGE_TAG){
      formatedString = `##@@@${id}##${medusa.app_name}@@@##${formatedString}`;
    }
    return formatedString;
  }

  /**
   * Produce the formatted string for displaying to the user
   * @param des {id: string, defaultString: string }
   * @param variables {[propName: string]: any}
   * @param options {FormatOptions}
   */
  format(des: Description = { id: '' }, variables: Variable, options: FormatOptions = {}): string|{}[] {

    const defaultString  = des.defaultMessage || des.defaultString || '';
     
    const hasVariables = variables && Object.keys(variables).length > 0;
    let tokenDelimiter = '';
    const tokenizedVariables: {[key: string]: string} = {};
    const elements: {[key: string]: {}} = {};
    const { React , component, tagName = 'span'} = options;
    // reader react nodes
    if(hasVariables){
      // Creates a token with a random UID that should not be guessable or
      // conflict with other parts of the `message` string.
      const uid = Math.floor(Math.random() * 0x10000000000).toString(16);
      
      const generateToken = ((): Function => {
        let counter = 0;
        return (): string => {
          counter += 1;
          return `ELEMENT-${uid}-${counter}`
        };
      })();
      // Splitting with a delimiter to support IE8. When using a regex
      // with a capture group IE8 does not include the capture group in
      // the resulting array.
      tokenDelimiter = `@__${uid}__@`;
      
      // Iterates over the `props` to keep track of any React Element
      // values so they can be represented by the `token` as a placeholder
      // when the `message` is formatted. This allows the formatted
      // message to then be broken-up into parts with references to the
      // React Elements inserted back in.


      Object.keys(variables).forEach((name): void => {
        const variable = variables[name];

        if (React && React.isValidElement(variable)) {
          const token = generateToken();
          tokenizedVariables[name] = tokenDelimiter + token + tokenDelimiter;
          elements[token] = variable;
        } else {
          tokenizedVariables[name] = variable;
        }
      });
    }
   
    let formattedMessage: string;
    if (!this.dictionary[des.id]) {
      if (typeof des === 'string') {
        error(`type of  "des" must be object, like:  {id: '', defaultString: ''}, instead of string `);
        formattedMessage = des || '';
      }else {
        warn(`there is no string with id="${des.id}" for locale: "${this.locale}", use defaultString or id as fallback`);
        const message = defaultString || des.id || '';
        try {
          const formatter =  new IntlMessageFormat(message, this.locale);
          formattedMessage = this.formatString(formatter, tokenizedVariables, des.id);
        } catch (e) {
          formattedMessage = message;
        }
      }
    }else {
      try {
        formattedMessage = this.formatString(this.dictionary[des.id], tokenizedVariables, des.id);
      } catch (e) {
        const desId = des.id ? ', using id as fallback.' : '';
        const message = defaultString ? ', using defaultString as fallback.' : desId;
        error(`format string: ${des.id} for locale  ${this.locale} ${message} \n${e}`);
        formattedMessage = defaultString || des.id || '';
      }
    }
    
    const hasElements = elements && Object.keys(elements).length > 0;
    if (hasElements) {

      // Split the message into parts so the React Element values captured
      // above can be inserted back into the rendered message. This
      // approach allows messages to render with React Elements while
      // keeping React's virtual diffing working properly.
      const nodes =  formattedMessage
        .split(tokenDelimiter)
        .filter((part): boolean => !!part)
        .map((part): object|string => elements[part] || part);
      const comp = component || tagName;
      
      // Needs to use `createElement()` instead of JSX, otherwise React will
      // warn about a missing `key` prop with rich-text message formatting.
      return React? React.createElement(comp, null, ...nodes): nodes;
    }
    return formattedMessage;
  }
}